const paths={home:'m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M7 3v4M17 3v4M4 10h16M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',moon:'M21 13A9 9 0 0 1 11 3a9 9 0 1 0 10 10Z',arrow:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',close:'M6 6L18 18M6 18L18 6',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',chat:'M21 11.5a8.5 8.5 0 0 1-8.5 8.5H3l2-5A8.5 8.5 0 1 1 21 11.5Z',shirt:'m8 3-6 4 3 5 3-2v11h8V10l3 2 3-5-6-4a4 4 0 0 1-8 0Z',wallet:'M20 7H5a2 2 0 0 1 0-4h13v4M3 5v14a2 2 0 0 0 2 2h15V7M20 11h-5v5h5',check:'m5 12 4 4L19 6',image:'M4 3h16v18H4ZM4 16l5-5 4 4 3-3 4 4M9 7h.01',pin:'M12 21s7-6 7-12a7 7 0 0 0-14 0c0 6 7 12 7 12ZM14 9a2 2 0 1 1-4 0 2 2 0 0 1 4 0Z',settings:'M4 7h16M4 17h16M9 4v6M16 14v6'};
paths.tree='M12 21V9M12 16l-4-4m4 1 4-4M7 15a4 4 0 0 1-3-7 5 5 0 0 1 8-5 5 5 0 0 1 8 5 4 4 0 0 1-3 7';
paths.bell='M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4';
const icon=k=>`<svg class="glyph" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.arrow}"/></svg>`;
if(typeof navigator!=='undefined'&&/Android/i.test(navigator.userAgent))document.documentElement.dataset.platform='android';
const greetings=['Hey, family!','Cousins, assemble.','Who brought the good plates?','Come get your hug.','The group chat, but organized.','Yes, there will be seconds.','We saved you a seat.','Somebody check on the grill.','Family first. Plates second.','A little soul. A lot of family.','We are family.','Your people are right here.','Bring yourself. And a container.'];
let greetingIndex=0;try{greetingIndex=(Number(sessionStorage.getItem('gw-greeting')||-1)+1)%greetings.length;sessionStorage.setItem('gw-greeting',greetingIndex)}catch{}
let greeting=greetings[greetingIndex];let reunionTab='details';let familyTab='people',notificationScope='leaders',readNotices=false;let selectedPeople=['sample-cousin'];const canPostPreview=true;
try{const n=localStorage.getItem('gw-notifications');if(['all','family','loved','selected','leaders','off'].includes(n))notificationScope=n}catch{}
const serifFonts=['DM Serif Text'];let serifFont='DM Serif Text';
function remember(k,v){try{localStorage.setItem(k,v)}catch{}}
try{const t=localStorage.getItem('gw-theme'),f=localStorage.getItem('gw-font'),sf=localStorage.getItem('gw-serif');if(['light','dark'].includes(t))document.documentElement.dataset.theme=t;document.documentElement.dataset.font=['serif','sans'].includes(f)?f:'serif';if(localStorage.getItem('gw-type-version')!=='dm-v1'){document.documentElement.dataset.font='serif';localStorage.setItem('gw-font','serif');localStorage.setItem('gw-type-version','dm-v1')}serifFont='DM Serif Text'}catch{}
const $=s=>document.querySelector(s);let view='home',planner=false,liked=false,vote='',shirtChoice='',rsvp='',toastTimer;
const button=(text,action,secondary=false)=>`<button class="button${secondary?' secondary':''}" data-action="${action}">${text}${icon('arrow')}</button>`;
const row=(glyph,title,detail,action)=>`<button class="list-row" data-action="${action}">${icon(glyph)}<span><strong>${title}</strong><p>${detail}</p></span><span class="arrow">${icon('arrow')}</span></button>`;
const postHead=(name,sub,initial='GW')=>`<div class="row post-head"><span class="avatar">${initial}</span><div><strong>${name}</strong><span class="muted">${sub}</span></div></div>`;
function home(){const next=!rsvp?['RSVP for your household','Let us know you’re coming.','rsvp']:!shirtChoice?['Choose your family shirts','Your RSVP is saved. Shirts are next.','shirts']:['Send your share','Your plans are saved. Contributions are next.','contribute'];return `<div class="intro"><div class="eyebrow">Our family, in one place</div><h1 class="greeting">${greeting}</h1></div><section class="card home-hero"><div><span class="badge">The next reunion</span><h2>More time<br>with our people.</h2><p class="muted small">Dates and location are on the way.</p><div style="margin-top:18px">${button('Reunion details','reunion')}</div></div><div><img class="photo" src="${familyPhotos.garden}" alt="Sample photo of a family smiling together outdoors"><p class="photo-caption">Sample photography · Vanessa Loring / Pexels</p></div></section><div class="columns home-grid"><section class="stack" aria-label="Family feed"><div class="feed-label"><h2>Family feed</h2><span class="badge">Family only</span></div><article class="card">${postHead('The planning crew','Sample photo post')}<div class="post-body"><h3>It starts with our people.</h3><p class="small muted" style="margin-top:7px">A place for all our favorite moments.</p></div><div class="post-photo"><img class="photo" src="${familyPhotos.generations}" alt="Sample photo of three generations smiling together"><p class="photo-caption">Sample photography · KATRIN BOLOVTSOVA / Pexels</p></div><div class="post-actions"><button data-action="like" aria-pressed="${liked}">${icon('heart')}${liked?'Loved':'Love'}</button><button data-action="comments">${icon('chat')}Comment</button><button data-action="memories">${icon('image')}All photos</button></div></article><article class="card">${postHead('A little family vote','Sample poll · Pick one')}<h3>What’s on the reunion playlist?</h3><div class="poll" role="radiogroup" aria-label="Choose one option">${['The classics','A little bit of everything','Let the cousins DJ'].map((x,i)=>`<button data-vote="${i}" role="radio" aria-checked="${vote===String(i)}">${vote!==''?`<span class="bar" style="--pct:${[35,45,20][i]}%"></span>`:''}<span>${x}</span><span class="poll-choice-end"><span class="poll-indicator ${vote===String(i)?'selected':''}">${vote===String(i)?icon('check'):''}</span>${vote!==''?[35,45,20][i]+'%':''}</span></button>`).join('')}</div><p class="small muted" style="margin-top:12px">${vote!==''?'Sample results · Your choice stays in this preview.':'One vote per family member.'}</p></article></section><aside class="home-context"><div class="stack"><section class="card reunion-hub"><h2>Your reunion</h2><div class="next-step"><span><strong>${next[0]}</strong><span class="small muted">${next[1]}</span></span></div><div style="margin:12px 0 20px">${button(next[2]==='rsvp'?'RSVP now':next[2]==='shirts'?'Choose your shirts':'Send your share',next[2])}</div>${row(rsvp?'check':'calendar','Your RSVP',rsvp||'Not answered yet','rsvp')}${row(shirtChoice?'check':'shirt','Family shirts',shirtChoice||'Pick a design and size','shirts')}${row('wallet','Your contribution','Send your share','contribute')}</section></div></aside></div>`}
function reunionOriginal(){return `<div class="intro"><div class="eyebrow">Green & White reunion</div><h1>Let’s make memories.</h1><p class="muted">All your reunion details, without the group-chat scroll.</p></div><div class="columns"><div class="stack"><section class="card hero"><span class="badge">In the works</span><h2>Save a little<br>room for family.</h2><div class="row" style="margin:19px 0">${icon('calendar')}<span>Dates to be announced</span></div><div class="row muted">${icon('pin')}<span>Location to be announced</span></div></section><section class="card"><h2 style="margin-bottom:20px">Your plans</h2>${row('calendar','RSVP for your household',rsvp||'One simple reply for everyone','rsvp')}${row('shirt','Choose your shirts',shirtChoice||'One bulk order for the family','shirts')}${row('wallet','Send your share','PayPal or Cash App','contribute')}</section></div><aside class="stack"><section class="card"><h2>The weekend</h2><div class="empty">${icon('calendar')}<p>Good things are coming.</p><p class="small muted">The planning crew will add the schedule here.</p></div></section><section class="card"><h3>A little clarity</h3><p class="small muted" style="margin-top:12px">Shirt choices and contributions stay together. You can see what you selected, what you’ve sent, and what the treasurer has confirmed.</p></section></aside></div>`}
function reunion(){return `<div class="intro"><div class="eyebrow">Green & White reunion</div><h1>Let’s make memories.</h1><p class="muted">Everything you need for our next time together.</p></div><div class="family-tabs" role="tablist" aria-label="Reunion sections">${[['details','home','Dashboard'],['plans','check','Plan'],['weekend','calendar','Calendar']].map(([id,g,label])=>`<button role="tab" id="reunion-${id}" aria-selected="${reunionTab===id}" aria-controls="reunion-panel" data-reunion-tab="${id}">${icon(g)}${label}</button>`).join('')}</div><section id="reunion-panel" role="tabpanel" aria-labelledby="reunion-${reunionTab}">${reunionTab==='plans'?`<section class="card"><h2>Your plans</h2>${row('calendar','RSVP for your household',rsvp||'One reply for everyone','rsvp')}${row('shirt','Choose your shirts',shirtChoice||'One bulk order for the family','shirts')}${row('wallet','Send your share','PayPal or Cash App','contribute')}</section>`:reunionTab==='weekend'?`<section class="card"><h2>The weekend</h2><div class="empty">${icon('calendar')}<p>The schedule is on its way.</p><p class="small muted">The planning crew will add activities and times here.</p></div></section>`:`<section class="card hero"><span class="badge">In the works</span><h2>More time with our people.</h2><div class="row" style="margin:20px 0">${icon('calendar')}Dates to be announced</div><div class="row">${icon('pin')}Location to be announced</div><p class="muted small" style="margin-top:24px">Shirt prices, deadlines and contribution amounts will be confirmed by the planners.</p></section>`}</section>`}
function family(){const tabs=[['people','People'],['memories','Memories'],['tree','Family tree']];return `<div class="intro"><h1>Our family.</h1><p class="muted">People, memories, and the stories that connect us.</p></div><div class="family-tabs" role="tablist" aria-label="Family sections">${tabs.map(([id,label])=>`<button role="tab" id="tab-${id}" aria-selected="${familyTab===id}" aria-controls="family-panel" data-family-tab="${id}">${icon(id==='people'?'people':id==='memories'?'image':'tree')}${label}</button>`).join('')}</div><section id="family-panel" role="tabpanel" aria-labelledby="tab-${familyTab}">${familyTab==='people'?`<div class="columns"><section class="card"><h2>Address book</h2><p class="muted" style="margin:12px 0 24px">A trusted place for the details each person chooses to share.</p><div class="directory-empty">${icon('people')}<h3>Start with your own card.</h3><p class="muted small">Add your details, then choose who can see them. No contact information is shared in this preview.</p>${button('Set up my contact card','contact-card')}</div></section><aside class="stack"><section class="card"><h3>Your family profile</h3><p class="small muted" style="margin:12px 0 18px">A familiar face, a little about you, and your place in the family.</p>${button('View your profile','you',true)}</section><p class="note">Contact cards are opt-in. Importing someone’s details will not publish them to the family.</p></aside></div>`:familyTab==='memories'?`<section><div class="section-head"><h2>Shared memories</h2><span class="badge">Sample photos</span></div><div class="memory-grid"><figure><img class="photo" src="${familyPhotos.garden}" alt="Sample family smiling outdoors"><figcaption>Vanessa Loring / Pexels</figcaption></figure><figure><img class="photo" src="${familyPhotos.generations}" alt="Sample photo of three generations"><figcaption>KATRIN BOLOVTSOVA / Pexels</figcaption></figure></div></section>`:`<section class="card tree-later"><img src="tree.svg" width="110" height="96" alt="Green and White oak grove"><h2>Our roots run deep.</h2><p class="muted">The reunion lead’s family research will help shape this space.</p><p class="small muted">Later, family members can submit names, photos, dates, and connections for admins and moderators to review.</p><span class="badge">Planned for a later phase</span></section>`}</section>`}
function you(){return `<div class="intro"><div class="eyebrow">Your little corner</div><h1>Hi, Lauren.</h1><p class="muted">A familiar face in the family.</p></div><div class="columns"><section class="card profile"><span class="avatar">L</span><h2>Lauren</h2><p class="muted small">Profile preview</p><span class="badge">Green & White family</span><p style="margin:22px 0" class="small muted">A short introduction and your family connections will go here.</p>${button('Edit profile','profile',true)}</section><section class="card">${row('calendar','My RSVP',rsvp||'Not sent yet','rsvp')}${row('shirt','My shirts',shirtChoice||'Choose a design','shirts')}${row('wallet','My contributions',escapeHtml(preview.contribution||'Nothing confirmed yet'),'contribute')}${row('bell','Notifications','Choose who you hear from','notification-settings')}</section></div><section class="card planner-section"><h2 class="list-heading">Planner tools</h2><p class="small muted">Admin / moderator preview</p>${row('settings','Planner overview','Everything in one place','planner')}${row('calendar','Reunion details','Dates, location and schedule','plan-details')}${row('chat','Post an update','Photos, announcements and polls','compose')}${row('shirt','Shirt totals','Manage the family order','shirt-totals')}${row('wallet','Contributions','Review reported payments','review-payments')}</section><p class="creator-credit">Built by <a href="https://loew.fi" target="_blank" rel="noopener noreferrer">Lauren Olivia</a><span>loew.fi</span></p>`}
function shirtSvg(color){return `<svg viewBox="0 0 180 190" aria-hidden="true"><path d="m55 22-42 28 22 37 20-13v97h70V74l20 13 22-37-42-28c-5 15-18 22-35 22S61 37 55 22Z" fill="${color}" stroke="currentColor" stroke-opacity=".12" stroke-width="2"/><image href="tree.svg" x="73" y="68" width="34" height="34"/><text x="90" y="114" text-anchor="middle" fill="${color==='#173c2a'?'#f5f3e8':'#173c2a'}" font-size="10" font-family="sans-serif" font-weight="700">GREEN & WHITE</text></svg>`}
function shirts(){return `<div class="intro"><div class="eyebrow">One family. One bulk order.</div><h1>Wear your roots.</h1><p class="muted">Choose a design and size. The planning crew handles the order together.</p></div><div class="columns"><section class="grid-two"><article class="card shirt-card"><div class="shirt">${shirtSvg('#173c2a')}</div><h3>Forest green</h3><p class="small muted">Concept design</p>${button('Choose this','shirt-green')}</article><article class="card shirt-card"><div class="shirt">${shirtSvg('#f2efdf')}</div><h3>Warm white</h3><p class="small muted">Concept design</p>${button('Choose this','shirt-white')}</article></section><aside class="stack"><section class="card"><h2>Your selection</h2><p style="margin:16px 0" class="muted small">${shirtChoice||'Pick a design to start your household’s shirt list.'}</p><p class="note">Price, order deadline, and available sizes will be confirmed by the planners.</p></section></aside></div>`}
function planning(){return `<div class="intro"><button class="text-button" data-view="you">← Back to You</button><div class="eyebrow">Planner preview · sample data</div><h1>A little less juggling.</h1><p class="muted">Keep the family informed and the reunion moving.</p></div><div class="columns"><div class="stack"><div class="grid-two"><div class="stat"><b>—</b><span>Confirmed attendees</span></div><div class="stat"><b>—</b><span>Shirts requested</span></div></div><section class="card"><h2 style="margin-bottom:20px">Start here</h2>${row('calendar','Reunion details','Set dates, location and schedule','plan-details')}${row('chat','Post an update','Announcements, photos or polls','compose')}${row('shirt','Shirt order','Design and size totals','shirt-totals')}${row('wallet','Contributions','Review reported payments','review-payments')}</section></div><aside class="stack"><section class="card"><h2>Keep it in the family.</h2><p class="muted small" style="margin:14px 0">Members can RSVP, choose shirts, and vote. Admins and moderators publish updates and media first.</p><p class="note">This preview shows the planner tools. In the real app, only authorized roles can access them.</p></section><section class="card"><h3>Payment destinations</h3><p class="small muted" style="margin:12px 0 18px">Only the treasurer can change where contributions go.</p>${button('Preview setup','payment-setup',true)}</section></aside></div>`}
function render(){const routes={home,reunion,family,you,shirts};$('#main').innerHTML=planner?planning():(routes[view]||home)();$('.bottom').innerHTML=[['home','home','Home'],['reunion','calendar','Reunion'],['family','people','Family'],['you','user','You']].map(([v,i,t])=>`<button data-view="${v}" ${((planner&&v==='you')||(!planner&&view===v))?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('');renderProfile();$('#notifications').innerHTML=icon('bell');$('#post-fab').hidden=!canPostPreview;$('#post-fab').innerHTML=icon('plus')+'<span>Post</span>';}
function go(v){close();if(v==='home'&&view!=='home'){greetingIndex=(greetingIndex+1)%greetings.length;greeting=greetings[greetingIndex]}view=v;planner=false;render();window.scrollTo({top:0,behavior:'auto'})}function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}function modal(title,html){$('#sheet-title').textContent=title;$('#sheet-body').innerHTML=html;$('#sheet').showModal()}function close(){if($('#sheet').open)syncComposerIfOpen();$('#sheet').close()}function setTheme(t){document.documentElement.dataset.theme=t;remember('gw-theme',t);renderProfile()}
function toggleTheme(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark')}
function setFont(f){document.documentElement.dataset.font=f;remember('gw-font',f);renderProfile();refreshWordmark()}
function chooseSerif(f){if(!serifFonts.includes(f))return;serifFont=f;remember('gw-serif',f);setFont('serif')}
function renderProfile(){document.documentElement.style.setProperty('--serif-font',`"${serifFont}", Georgia, serif`);const dark=document.documentElement.dataset.theme!=='light',serif=document.documentElement.dataset.font==='serif';$('#profile-popout').innerHTML=`<div class="profile-summary"><span class="avatar">${escapeHtml(preview.profile.name.slice(0,1))}</span><span><strong>${escapeHtml(preview.profile.name)}</strong><small>Your family profile</small></span></div><button class="button full" data-view="you">${icon('user')}Go to You</button><div class="profile-shortcuts">${row('calendar','Your RSVP','Update your plans','rsvp')}${row('shirt','Family shirts','Choose your size','shirts')}${row('wallet','Send your share','View contributions','contribute')}</div><div class="profile-controls"><div class="control-label">Appearance</div><div class="sliding-control" role="group" aria-label="Color theme" data-selected="${dark?1:0}"><span class="slider" aria-hidden="true"></span><button data-theme-choice="light" aria-pressed="${!dark}">${icon('sun')}Light</button><button data-theme-choice="dark" aria-pressed="${dark}">${icon('moon')}Dark</button></div><div class="sliding-control font-control" role="group" aria-label="Heading style" data-selected="${serif?0:1}"><span class="slider" aria-hidden="true"></span><button class="serif-sample" data-font-choice="serif" aria-label="Serif headings" aria-pressed="${serif}">gw</button><button class="sans-sample" data-font-choice="sans" aria-label="Sans serif headings" aria-pressed="${!serif}">gw</button></div></div>`}
function fitWordmark(){const top=$('.wordmark-top'),bottom=$('.wordmark-bottom');if(!top?.getBoundingClientRect||!bottom?.getBoundingClientRect)return;const size=parseFloat(getComputedStyle(top).fontSize);bottom.style.fontSize=size+'px';const tw=top.getBoundingClientRect().width,bw=bottom.getBoundingClientRect().width;if(tw>0&&bw>0)bottom.style.fontSize=(size*tw/bw)+'px'}
function refreshWordmark(){if(document.fonts?.load)document.fonts.load(`24px "${serifFont}"`).then(fitWordmark);else fitWordmark()}
function hideProfile(){const pop=$('#profile-popout');if(pop.hidePopover)pop.hidePopover()}

function notificationSettings(){return modal('Notifications',`<p class="muted small">Choose whose updates you want alerts for.</p><div class="notification-choices">${[['all','All Family'],['selected','Selected Family Members'],['leaders','Family Leaders'],['off','Off']].map(([id,label])=>`<button class="list-row" data-notification-scope="${id}" aria-pressed="${notificationScope===id}"><span>${label}</span><span class="arrow">${notificationScope===id?icon('check'):''}</span></button>`).join('')}</div>${notificationScope==='selected'?`<label class="member-choice"><input type="checkbox" data-selected-person="sample-cousin" ${selectedPeople.includes('sample-cousin')?'checked':''}>Sample family member</label><p class="small muted">Real members will appear after sign-in is connected.</p>`:''}<p class="note" style="margin-top:20px">Preferences are saved on this device for the preview. Push delivery is not connected yet. On iPhone, you’ll add the app to your Home Screen before enabling notifications.</p>`)}
function notifications(){const sample=[{kind:'leaders',title:'Welcome from the planning crew',body:'A sample family-leader announcement.'},{kind:'family',title:'A new family memory',body:'A sample photo update from a family member.'}];const shown=sample.filter(n=>notificationScope==='all'||notificationScope==='leaders'&&n.kind==='leaders'||notificationScope==='selected'&&n.kind==='family'&&selectedPeople.length);modal('Notifications',`<div class="row spread"><span class="badge">Sample notifications</span><button class="text-button" data-action="notification-settings">Settings</button></div>${shown.length?shown.map(n=>`<article class="notification-item"><h3>${n.title}</h3><p class="small muted">${n.body}</p><span class="small muted">${readNotices?'Read':'Unread'}</span></article>`).join(''):'<p style="margin:24px 0" class="muted">No updates for this filter.</p>'}${shown.length?button('Mark all read','read-notifications',true):''}`)}
function act(a){if(previewAction(a))return;if(a==='notifications')return notifications();if(a==='notification-settings')return notificationSettings();if(a==='read-notifications'){readNotices=true;return notifications()}if(a==='contact-card')return modal('Your contact card',`<p class="muted small">Design preview. Nothing entered here is uploaded or shared.</p><label for="contact-name">Name</label><input id="contact-name" autocomplete="name" placeholder="Your name"><label for="contact-email">Email</label><input id="contact-email" type="email" autocomplete="email" placeholder="Optional"><label for="contact-phone">Phone</label><input id="contact-phone" type="tel" autocomplete="tel" placeholder="Optional"><label for="contact-visibility">Who can see these details?</label><select id="contact-visibility"><option>Only me</option><option>Selected family members</option><option>Family leaders</option><option>All approved family members</option></select><p class="note" style="margin-top:20px">Live sharing will require sign-in and your explicit review. This preview does not save contact information.</p>`);
if(a==='memories')return modal('Shared memories',`<p class="small muted">Sample photography for the design preview.</p><div class="gallery-grid" style="margin-top:18px"><img class="photo" src="${familyPhotos.garden}" alt="Family smiling outdoors"><img class="photo" src="${familyPhotos.generations}" alt="Three generations together"></div>`);if(a==='planner'){planner=true;render();window.scrollTo({top:0});return}if(['home','reunion','family','you','shirts'].includes(a))return go(a);if(a==='theme')return toggleTheme();if(a==='like'){liked=!liked;return render()}if(a==='rsvp')return modal('Count us in.',`<p class="muted small">A simple RSVP for your household. Preview only.</p><label for="rsvp-count">How many people?</label><select id="rsvp-count">${[1,2,3,4,5,6,7,8].map(n=>`<option>${n}</option>`).join('')}</select><label for="rsvp-status">Your plans</label><select id="rsvp-status"><option>Planning to come</option><option>Still deciding</option><option>Can’t make it</option></select>${button('Save preview RSVP','save-rsvp')}`);if(a==='save-rsvp'){preview.rsvp={count:$('#rsvp-count').value,status:$('#rsvp-status').value};rsvp=$('#rsvp-count').value+' people · '+$('#rsvp-status').value;render();return modal('RSVP saved',`<div class="step-nav"><span class="current">1. RSVP ✓</span><span>2. Shirts</span><span>3. Contribution</span></div><p class="muted">${escapeHtml(rsvp)}</p><p class="small muted" style="margin-top:10px">Preview saved for this visit only.</p>${button('Next: family shirts','shirts')}<div style="margin-top:10px">${button('Back to Home','home',true)}</div>`)}
if(a.startsWith('shirt-')&&['shirt-green','shirt-white'].includes(a)){const color=a==='shirt-green'?'Forest green':'Warm white';return modal('Your family shirt',`<p class="muted">${color} · concept design</p><label for="shirt-size">Size</label><select id="shirt-size">${['Youth S','Youth M','Youth L','S','M','L','XL','2XL','3XL'].map(s=>`<option ${preview.shirt?.design===color&&preview.shirt?.size===s?'selected':''}>${s}</option>`).join('')}</select><label for="shirt-quantity">Quantity</label><select id="shirt-quantity">${[1,2,3,4,5].map(n=>`<option ${preview.shirt?.design===color&&preview.shirt?.quantity===n?'selected':''}>${n}</option>`).join('')}</select><button class="button full" style="margin-top:20px" data-save-shirt="${color}">Save selection</button><p class="small muted" style="margin-top:12px">Sample sizes. No purchase or payment is made.</p><div class="form-actions">${button('Back: RSVP','rsvp',true)}<button class="text-button" data-preview-action="clear-shirt">Clear my selection</button></div>`)}
if(a==='contribute')return modal('Send your share',`${previewNotice}${preview.contribution?`<p class="badge">${escapeHtml(preview.contribution)}</p>`:''}<p class="muted small">Your household total will appear here once the planners set the costs.</p><div class="note" style="margin-top:17px">Recipient: not configured. The treasurer’s verified name and handle will be shown before you leave the app.</div><button class="payment-choice" data-action="payment-unset">${icon('wallet')}<span><strong>PayPal</strong><small>Open a link with your amount</small></span></button><button class="payment-choice" data-action="payment-unset">${icon('wallet')}<span><strong>Cash App</strong><small>Open the treasurer’s payment request</small></span></button><p class="small muted" style="margin-top:18px">After sending, report it here. Your status stays “Awaiting confirmation” until the treasurer verifies receipt.</p>${button('Preview “I’ve sent it”','sent-preview',true)}<div>${button('Back: shirts','shirts',true)}</div>`);if(a==='payment-unset')return toast('Preview only. No payment destination has been connected.');if(a==='sent-preview')return modal('Awaiting confirmation',`<div class="row" style="margin-bottom:15px">${icon('check')}<strong>Demo report by you</strong></div><p class="muted">The treasurer checks the payment account and confirms receipt. Opening a payment link never marks your contribution paid.</p><p class="note" style="margin-top:20px">This is a sample status. No money was sent or received.</p>`);
if(a==='payment-setup')return modal('Treasurer setup',`<p class="muted">Connect verified PayPal.Me and Cash App request links, then check the displayed recipient on both services.</p><div class="note" style="margin:20px 0">No links are active in this preview. In the real app, destination changes are restricted to the treasurer and recorded for review.</div>`);if(a==='review-payments')return modal('Confirm contributions',`<p class="muted">No real contributions yet.</p><div class="card" style="margin-top:20px"><span class="badge">Sample status</span><h3 style="margin-top:12px">Awaiting confirmation</h3><p class="small muted" style="margin:12px 0">Check recipient, sender, amount and transaction in the payment service before confirming. A screenshot alone isn’t proof of receipt.</p></div>`);
if(a==='quick')return modal(planner?'Keep things moving':'Your reunion, at a glance',`<div class="stack">${button(planner?'Post an update':'Update your RSVP',planner?'compose':'rsvp')}${button('Choose your shirts','shirts',true)}${button('Send your share','contribute',true)}</div>`);
const details={comments:['Say hello','Member conversations will live below each post. This preview does not send comments.'],connection:['Find your connection','Search for a family member, choose your relationship, and ask them to confirm. Ancestor profiles can be added separately.'],profile:['Your microprofile','Your photo, name, a short introduction, and confirmed family connections. Your contact information stays private by default.'],'plan-details':['The next reunion','Dates, location, schedule and contribution amounts are still to be decided.'],compose:['Keep the family in the loop','Admins and moderators can start with an announcement, a photo or a poll. Publishing is not connected in this preview.'],'shirt-totals':['One bulk order','The planners will see total shirts by design and size, plus each household’s selections. There are no real orders yet.']};if(details[a])modal(details[a][0],`<p class="muted">${details[a][1]}</p>`)}
// Isolated in-memory demo state. Reload or reset clears every entered detail.
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function safeUrl(value){try{const url=new URL(String(value).trim());return ['https:','http:'].includes(url.protocol)&&!url.username&&!url.password&&url.hostname?url.href:null}catch{return null}}
function parsePreviewLink(text){const candidates=String(text).matchAll(/https?:\/\/[^\s<>"']+/gi);for(const match of candidates){const raw=match[0].replace(/[.,!?;:]+$/,'').replace(/\)+$/,tail=>{const left=(match[0].match(/\(/g)||[]).length,right=(match[0].match(/\)/g)||[]).length;return tail.slice(0,Math.max(0,tail.length-(right-left)))});const href=safeUrl(raw);if(!href)continue;const url=new URL(href),host=url.hostname.replace(/^www\./,'');const providers=[['YouTube',['youtube.com','m.youtube.com','youtu.be']],['Spotify',['open.spotify.com']],['Apple Music',['music.apple.com']],['Instagram',['instagram.com']],['TikTok',['tiktok.com','vm.tiktok.com']],['Facebook',['facebook.com','m.facebook.com','fb.watch']],['Threads',['threads.net','threads.com']],['X',['x.com','twitter.com']],['Bluesky',['bsky.app']]];const provider=url.protocol==='https:'?providers.find(([,hosts])=>hosts.includes(host))?.[0]:null;return {href,raw,index:match.index,provider:provider||'Link',host,supported:!!provider}}return null}
function convertComposerLink(draft){if(draft.attachment)return false;const link=parsePreviewLink(draft.text);if(!link)return false;draft.text=draft.text.slice(0,link.index)+draft.text.slice(link.index+link.raw.length);draft.attachment=link;return true}
function restoreComposerLink(draft){const link=draft.attachment||draft.removed;if(!link)return false;const index=Math.min(link.index,draft.text.length);draft.text=draft.text.slice(0,index)+link.raw+draft.text.slice(index);draft.attachment=null;draft.removed=null;return true}
const freshPreview=()=>({posts:[],reactions:{},comments:{},profile:{name:'Lauren',bio:'',socials:[]},contact:null,details:{date:'',location:'',schedule:''},shirt:null,rsvp:null,contribution:null,orderReviewed:false});
let preview=freshPreview(),previewId=0,composer={text:'',attachment:null,removed:null},activePost='photo',replyParent=null,emojiPage=0,emojiQuery='';
const previewNotice='<p class="note">Session-only preview. No uploads, messages, orders or payments are sent. Reload or reset to clear your entries.</p>';
function knownPost(id){return ['photo','poll',...preview.posts.map(p=>p.id)].includes(id)}
function toggleReaction(id,emoji){if(!knownPost(id)||!emojiChoices().some(e=>e.native===emoji))return false;const set=preview.reactions[id]||(preview.reactions[id]=[]);const index=set.indexOf(emoji);if(index<0)set.push(emoji);else set.splice(index,1);return true}
let allEmojiCache;function emojiChoices(){if(allEmojiCache)return allEmojiCache;const data=typeof emojiData!=='undefined'?emojiData:[{name:'Heart',keywords:['love'],skins:['❤️']},{name:'Clap',keywords:['yay'],skins:['👏']},{name:'Laugh',keywords:['funny'],skins:['😂']},{name:'Celebrate',keywords:['party'],skins:['🎉']},{name:'Thanks',keywords:['pray'],skins:['🙏']}];return allEmojiCache=data.flatMap(e=>e.skins.map((native,i)=>({native,name:e.name+(i?' · skin tone '+i:''),search:[e.id,e.name,...e.keywords].join(' ').toLowerCase()})))}
function addComment(id,text,parent=null){text=String(text).trim();if(!knownPost(id)||!text||text.length>1500)return false;const comments=preview.comments[id]||(preview.comments[id]=[]);let depth=0,cursor=parent;while(cursor){const p=comments.find(c=>c.id===cursor);if(!p)return false;depth++;cursor=p.parent;if(depth>=4)return false}comments.push({id:'c'+(++previewId),parent,text,name:preview.profile.name});return true}
function postActions(id,photos=false){const reactions=preview.reactions[id]||[],count=(preview.comments[id]||[]).length;return `<div class="reaction-chips" aria-label="Reactions">${reactions.map(e=>`<button class="reaction-chip" data-reaction-post="${id}" data-emoji="${escapeHtml(e)}" aria-pressed="true" aria-label="Remove your ${escapeHtml(emojiChoices().find(x=>x.native===e)?.name||'emoji')} reaction">${escapeHtml(e)} <span>1</span></button>`).join('')}</div><div class="post-actions"><button data-react-post="${id}">${icon('heart')}React</button><button data-comment-post="${id}">${icon('chat')}Comment${count?' · '+count:''}</button>${photos?`<button data-action="memories">${icon('image')}All photos</button>`:''}</div>`}
function attachmentHtml(a){return `<div class="link-preview">${icon(a.provider==='Link'?'arrow':'image')}<div><span class="badge">${escapeHtml(a.provider)} preview</span><p><a href="${escapeHtml(a.href)}" target="_blank" rel="noopener noreferrer">${escapeHtml(a.host)}</a></p><p class="small muted">${a.supported?'Metadata pending. Title, image and playback aren’t loaded in this prototype.':'Link preview only. No metadata or embedded content is loaded.'}</p><span class="link-url small">${escapeHtml(a.href)}</span></div></div>`}
const baseHome=home;home=function(){let html=baseHome().replace(/<div class="post-actions">[\s\S]*?<\/div><\/article>/,postActions('photo',true)+'</article>').replace('One vote per family member.','One preview vote per family member.');html=html.replace('</p></article></section><aside',`</p>${postActions('poll')}</article></section><aside`);const posts=preview.posts.map(p=>`<article class="card">${postHead(escapeHtml(p.name),'Session-only preview post',escapeHtml(p.name.slice(0,1)))}<div class="post-body preview-prose">${escapeHtml(p.text)}</div>${p.attachment?attachmentHtml(p.attachment):''}${postMedia(p)}${postActions(p.id)}</article>`).join('');html=html.replace('<span class="badge">Family only</span></div>','<span class="badge">Family only · sample feed</span></div>'+posts);if(preview.details.date||preview.details.location)html=html.replace('Dates and location are on the way.',escapeHtml([preview.details.date,preview.details.location].filter(Boolean).join(' · '))+' · Preview');return html};
const baseReunion=reunion;reunion=function(){let html=baseReunion();html=html.replace('Dates to be announced',escapeHtml(preview.details.date||'Dates to be announced')).replace('Location to be announced',escapeHtml(preview.details.location||'Location to be announced'));if(preview.details.schedule)html=html.replace('<div class="empty">'+icon('calendar')+'<p>The schedule is on its way.</p><p class="small muted">The planning crew will add activities and times here.</p></div>',`<p class="badge">Preview schedule</p><div class="preview-prose schedule-preview">${escapeHtml(preview.details.schedule)}</div>`);return html};
const baseYou=you;you=function(){let html=baseYou();html=html.replace('Hi, Lauren.','Hi, '+escapeHtml(preview.profile.name)+'.').replace('<h2>Lauren</h2>','<h2>'+escapeHtml(preview.profile.name)+'</h2>').replace('A short introduction and your family connections will go here.',escapeHtml(preview.profile.bio||'A short introduction and your family connections will go here.'));if(preview.profile.socials.length)html=html.replace(button('Edit profile','profile',true),`<div class="social-links">${preview.profile.socials.map(url=>`<a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(new URL(url).hostname)}</a>`).join('')}</div>`+button('Edit profile','profile',true));return html};
const basePlanning=planning;planning=function(){return basePlanning().replace('<b>—</b><span>Confirmed attendees</span>',`<b>${preview.rsvp?.status==='Planning to come'?escapeHtml(preview.rsvp.count):'0'}</b><span>Preview attendees</span>`).replace('<b>—</b><span>Shirts requested</span>',`<b>${preview.shirt?.quantity||0}</b><span>Your preview shirts</span>`)};
const baseModal=modal;modal=function(title,html){baseModal(title,html+`<div class="preview-footer"><button class="text-button" data-preview-action="cancel">Close / cancel</button><button class="text-button" data-preview-action="reset">Reset preview</button></div>`)};
function showComposer(){modal('Post to the family',`${previewNotice}<form id="composer-form"><label for="post-text">Your update</label><textarea id="post-text" maxlength="3000" rows="5" placeholder="Write a little something, or paste a link…">${escapeHtml(composer.text)}</textarea><p class="small muted">3,000 characters max. Paste a YouTube, music or social link for a safe preview. Ctrl/⌘ + Enter posts here.</p><div id="composer-attachment">${composerAttachment()}</div>${composerExtras()}<div class="form-actions"><button type="button" class="button secondary" data-preview-action="convert-link">Preview link</button><button class="button" type="submit">Post in preview ${icon('plus')}</button><button class="text-button" type="button" data-preview-action="discard-draft">Discard draft</button></div><p class="form-error" id="composer-error" role="alert"></p></form>`)}
function composerAttachment(){return composer.attachment?attachmentHtml(composer.attachment)+`<div class="form-actions"><button class="text-button" type="button" data-preview-action="restore-link">Restore URL to text</button><button class="text-button" type="button" data-preview-action="remove-link">Remove attachment</button></div>`:composer.removed?'<button class="text-button" type="button" data-preview-action="restore-link">Undo removal · restore URL</button>':''}
function syncComposer(){const input=$('#post-text');if(input)composer.text=input.value}
function updateComposerAttachment(){const text=$('#post-text');if(text)text.value=composer.text;const box=$('#composer-attachment');if(box)box.innerHTML=composerAttachment()}
function publishPreviewPost(){syncComposer();syncPostExtras();if(composer.poll&&(!composer.poll.question||composer.poll.options.length<2||composer.poll.options.length>6)){$('#composer-error').textContent='A poll needs a question and 2–6 choices.';return false}if(composer.text.length>3000||(!composer.text.trim()&&!composer.attachment&&!composer.photos?.length&&!composer.files?.length&&!composer.poll)){ $('#composer-error').textContent='Add an update or a link (up to 3,000 characters).';return false}preview.posts.unshift({id:'post'+(++previewId),name:preview.profile.name,text:composer.text.trim(),attachment:composer.attachment,photos:composer.photos||[],poll:composer.poll||null});close();composer={text:'',attachment:null,removed:null};go('home');toast('Posted in this preview only.');return true}
function composerExtras(){return `<div class="composer-tools"><label class="button secondary" for="post-photos">${icon('image')}Add photos</label><input id="post-photos" class="visually-hidden" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple><button type="button" class="button secondary" data-preview-action="toggle-poll">${icon('chat')}${composer.poll?'Remove poll':'Add poll'}</button></div><p class="small muted">Up to 4 photos, 8 MB each. Files stay on this device in this preview.</p><div id="post-photo-previews">${photoDraftHtml()}</div>${composer.poll?`<div class="poll-draft"><label for="poll-question">Poll question</label><input id="poll-question" maxlength="160" value="${escapeHtml(composer.poll.question)}"><label for="poll-options">Choices · one per line</label><textarea id="poll-options" maxlength="600" rows="4">${escapeHtml(composer.poll.options.join('\n'))}</textarea><p class="small muted">2–6 choices. One preview vote per person.</p></div>`:''}`}
function photoDraftHtml(){return (composer.photos||[]).map((p,i)=>`<figure><img src="${p.src}" alt="${escapeHtml(p.name)}"><button type="button" data-remove-photo="${i}" aria-label="Remove ${escapeHtml(p.name)}">${icon('close')}</button></figure>`).join('')}
function syncPostExtras(){if(composer.poll){const q=$('#poll-question'),o=$('#poll-options');if(q)composer.poll.question=q.value.trim().slice(0,160);if(o)composer.poll.options=o.value.split('\n').map(x=>x.trim().slice(0,100)).filter(Boolean)}}
function postMedia(p){return `${p.photos?.length?`<div class="posted-photos">${p.photos.map(photo=>`<img class="photo" src="${photo.src}" alt="${escapeHtml(photo.name)}">`).join('')}</div>`:''}${p.poll?`<h3 class="section-gap">${escapeHtml(p.poll.question)}</h3><div class="poll" role="radiogroup" aria-label="Choose one option">${p.poll.options.map((o,i)=>`<button data-local-poll="${p.id}" data-option="${i}" role="radio" aria-checked="${p.poll.vote===i}"><span>${escapeHtml(o)}</span><span class="poll-indicator ${p.poll.vote===i?'selected':''}">${p.poll.vote===i?icon('check'):''}</span></button>`).join('')}</div>`:''}`}
async function loadPreviewPhotos(files){const target=composer;const chosen=Array.from(files).slice(0,4-(composer.photos?.length||0));if(!chosen.length)return toast('Keep up to 4 photos per preview post.');for(const file of chosen){if(!['image/jpeg','image/png','image/webp','image/avif'].includes(file.type)||file.size>8*1024*1024){toast('Choose JPEG, PNG, WebP or AVIF photos under 8 MB.');continue}try{const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});if(composer!==target)return;if(!String(src).startsWith('data:image/'))continue;(composer.photos||(composer.photos=[])).push({src,name:file.name.slice(0,120)});}catch{toast('That photo could not be read. Try another file.')}}const box=$('#post-photo-previews');if(box)box.innerHTML=photoDraftHtml()}
function showReactions(id){if(!knownPost(id))return;activePost=id;emojiPage=0;emojiQuery='';modal('A little reaction',`<p class="small muted">Your preview reactions stay in this session. Tap again to remove.</p><div class="quick-emoji">${['❤️','👏','😂','🎉','🙏'].map(e=>`<button data-reaction-post="${id}" data-emoji="${e}" aria-label="React ${e}">${e}</button>`).join('')}</div><label for="emoji-search">Search all emoji and skin tones</label><input id="emoji-search" type="search" placeholder="Heart, smile, food…" autocomplete="off"><div id="emoji-results"></div>`);renderEmojiResults()}
function renderEmojiResults(){const matches=emojiChoices().filter(e=>!emojiQuery||e.search.includes(emojiQuery)||e.native.includes(emojiQuery)),shown=matches.slice(0,80*(emojiPage+1)),selected=preview.reactions[activePost]||[];$('#emoji-results').innerHTML=`<p class="small muted emoji-count" role="status">${shown.length} of ${matches.length} choices</p><div class="emoji-grid">${shown.map(e=>`<button title="${escapeHtml(e.name)}" aria-label="${escapeHtml(e.name)}" aria-pressed="${selected.includes(e.native)}" data-reaction-post="${activePost}" data-emoji="${escapeHtml(e.native)}">${escapeHtml(e.native)}</button>`).join('')}</div>${shown.length<matches.length?'<button class="button secondary full" data-preview-action="more-emoji">Show more emoji</button>':''}`}
function commentTree(id,parent=null,depth=0){return (preview.comments[id]||[]).filter(c=>c.parent===parent).map(c=>`<article class="comment" style="--depth:${depth}"><strong>${escapeHtml(c.name)}</strong><span class="badge">Preview</span><p class="preview-prose">${escapeHtml(c.text)}</p>${depth<3?`<button class="text-button" data-reply-id="${c.id}">Reply</button>`:''}${commentTree(id,c.id,depth+1)}</article>`).join('')}
function showComments(id,parent=null){if(!knownPost(id))return;activePost=id;replyParent=parent;const target=(preview.comments[id]||[]).find(c=>c.id===parent);modal('Family conversation',`${previewNotice}<div class="comments-list">${commentTree(id)||'<p class="muted">Start this preview conversation.</p>'}</div><form id="comment-form"><label for="comment-text">${target?'Reply to '+escapeHtml(target.name):'Add a comment'}</label>${target?'<button class="text-button" type="button" data-preview-action="cancel-reply">Cancel reply</button>':''}<textarea id="comment-text" maxlength="1500" rows="3" required placeholder="Say hello…"></textarea><p class="small muted">1,500 characters max. Ctrl/⌘ + Enter to add.</p><button class="button" type="submit">${target?'Add reply':'Add comment'}</button><p id="comment-error" class="form-error" role="alert"></p></form>`);$('#comment-text')?.focus?.()}
function showProfile(){modal('Edit your profile',`${previewNotice}<form id="profile-form"><label for="profile-name">Name</label><input id="profile-name" maxlength="60" required value="${escapeHtml(preview.profile.name)}"><label for="profile-bio">A little about you</label><textarea id="profile-bio" rows="3" maxlength="400">${escapeHtml(preview.profile.bio)}</textarea><label for="profile-socials">Social links · optional</label><textarea id="profile-socials" rows="4" maxlength="1600" placeholder="One http:// or https:// link per line">${escapeHtml(preview.profile.socials.join('\n'))}</textarea><p class="small muted">Up to 4 links. No accounts are connected.</p><p id="profile-error" class="form-error" role="alert"></p><button class="button" type="submit">Save preview profile</button></form>`)}
function showDetails(){modal('Edit reunion details',`${previewNotice}<form id="details-form"><label for="reunion-date">Reunion date</label><input type="date" id="reunion-date" value="${escapeHtml(preview.details.date)}"><label for="reunion-location">Location</label><input id="reunion-location" maxlength="160" value="${escapeHtml(preview.details.location)}" placeholder="To be announced"><label for="reunion-schedule">Weekend schedule</label><textarea id="reunion-schedule" rows="6" maxlength="2000" placeholder="Friday, 6 pm · Welcome dinner&#10;Saturday, noon · Family picnic">${escapeHtml(preview.details.schedule)}</textarea><button class="button" type="submit">Save preview details</button><p id="details-error" class="form-error" role="alert"></p></form>`)}
function showShirtTotals(){const items=[{design:'Forest green',size:'M',quantity:2,household:'Sample household'},...(preview.shirt?[{...preview.shirt,household:'Your preview household'}]:[])];const totals=new Map();for(const s of items){const key=s.design+' · '+s.size;totals.set(key,(totals.get(key)||0)+s.quantity)}modal('Family shirt totals',`${previewNotice}<span class="badge">Sample ordering worksheet</span><div class="totals-list">${[...totals].map(([label,n])=>`<div class="row spread"><span>${escapeHtml(label)}</span><strong>${n}</strong></div>`).join('')}</div><p><strong>${items.reduce((n,s)=>n+s.quantity,0)} shirts</strong> across ${items.length} sample selection${items.length===1?'':'s'}.</p><p class="small muted">Includes 2 demo shirts plus your saved selection. Prices, supplier and order deadline are unset.</p><div class="order-households">${items.map(s=>`<p>${escapeHtml(s.household)}: ${escapeHtml(s.design)} / ${escapeHtml(s.size)} × ${s.quantity}</p>`).join('')}</div><p class="note">${preview.orderReviewed?'Worksheet marked reviewed in the demo. No order was placed.':'Review this worksheet before any future real order. No checkout or supplier is connected.'}</p><div class="form-actions">${button('Edit my selection','shirts',true)}<button class="button" data-preview-action="review-order">${preview.orderReviewed?'Undo review':'Mark demo reviewed'}</button></div>`)}
function showContributionReview(){modal('Review contributions',`${previewNotice}<span class="badge">Demo review · no payment verification</span><h3 class="section-gap">Your preview household</h3><p class="muted">${preview.contribution||'No demo report submitted yet.'}</p><p class="note section-gap">Amount and recipient are unset. Nothing here is evidence of payment. In production, the treasurer must verify receipt in the payment service.</p><div class="form-actions"><button class="button secondary" data-preview-action="demo-report">Create sample report</button>${preview.contribution?'<button class="button" data-preview-action="demo-approve">Simulate review complete</button><button class="text-button" data-preview-action="demo-question">Flag for demo follow-up</button><button class="text-button" data-preview-action="demo-clear">Clear report</button>':''}</div>`)}
function showContact(){const c=preview.contact||{name:'',email:'',phone:'',optIn:false};modal('Your private contact card',`${previewNotice}<p class="muted small">Nothing entered here is uploaded or shared. Use sample details.</p><form id="contact-form"><label for="contact-name">Name</label><input id="contact-name" maxlength="60" value="${escapeHtml(c.name)}"><label for="contact-email">Email · optional</label><input id="contact-email" type="email" maxlength="160" value="${escapeHtml(c.email)}"><label for="contact-phone">Phone · optional</label><input id="contact-phone" type="tel" maxlength="40" value="${escapeHtml(c.phone)}"><label class="member-choice"><input id="contact-optin" type="checkbox" ${c.optIn?'checked':''}>Preview opting in to a family contact card</label><p class="note">${c.optIn?'Opt-in selected in this demo only.':'Private by default.'} No contacts are requested, imported or published.</p><button class="button" type="submit">Save private preview</button></form>`)}
function showRsvp(){modal('Count us in.',`${previewNotice}<form id="rsvp-form"><label for="rsvp-count">How many people?</label><select id="rsvp-count">${[1,2,3,4,5,6,7,8].map(n=>`<option ${preview.rsvp?.count===String(n)?'selected':''}>${n}</option>`).join('')}</select><label for="rsvp-status">Your plans</label><select id="rsvp-status">${['Planning to come','Still deciding','Can’t make it'].map(s=>`<option ${preview.rsvp?.status===s?'selected':''}>${s}</option>`).join('')}</select><div class="form-actions"><button class="button" type="submit">Save preview RSVP</button><button type="button" class="text-button" data-preview-action="clear-rsvp">Clear RSVP</button></div></form>`)}
function previewAction(action){if(action==='compose'){showComposer();return true}if(action==='profile'){showProfile();return true}if(action==='plan-details'){showDetails();return true}if(action==='shirt-totals'){showShirtTotals();return true}if(action==='review-payments'){showContributionReview();return true}if(action==='contact-card'){showContact();return true}if(action==='rsvp'){showRsvp();return true}if(action==='comments'){showComments('photo');return true}if(action==='like'){toggleReaction('photo','❤️');render();return true}if(action==='sent-preview'){preview.contribution='Awaiting confirmation · demo report only';return false}return false}
function resetPreview(){close();preview=freshPreview();composer={text:'',attachment:null,removed:null};rsvp='';shirtChoice='';vote='';liked=false;replyParent=null;close();go('home');toast('Preview entries cleared. Appearance preferences kept.')}
function doPreviewAction(action){if(action==='toggle-poll'){syncComposer();syncPostExtras();composer.poll=composer.poll?null:{question:'',options:[]};return showComposer()}if(action==='cancel'){close();return}if(action==='discard-draft'){composer={text:'',attachment:null,removed:null};return showComposer()}if(action==='reset'){modal('Reset this preview?',`<p class="muted">Clear session posts, reactions, comments, profile, contact card, reunion plans and demo statuses? Your appearance preferences stay.</p><div class="form-actions"><button class="button" data-preview-action="confirm-reset">Reset all preview entries</button><button class="button secondary" data-preview-action="cancel">Keep editing</button></div>`);return}if(action==='confirm-reset')return resetPreview();if(action==='convert-link'){syncComposer();if(!convertComposerLink(composer))toast(composer.attachment?'One attachment at a time.':'Paste a valid http:// or https:// link first.');return updateComposerAttachment()}if(action==='restore-link'){syncComposer();restoreComposerLink(composer);return updateComposerAttachment()}if(action==='remove-link'){syncComposer();composer.removed=composer.attachment;composer.attachment=null;return updateComposerAttachment()}if(action==='more-emoji'){emojiPage++;return renderEmojiResults()}if(action==='cancel-reply')return showComments(activePost);if(action==='review-order'){preview.orderReviewed=!preview.orderReviewed;return showShirtTotals()}if(action==='demo-report')preview.contribution='Awaiting confirmation · demo report only';if(action==='demo-approve')preview.contribution='Demo review complete · no funds verified';if(action==='demo-question')preview.contribution='Demo follow-up requested · no notification sent';if(action==='demo-clear')preview.contribution=null;if(action.startsWith('demo-'))return showContributionReview();if(action==='clear-shirt'){preview.shirt=null;shirtChoice='';preview.orderReviewed=false;close();go('shirts');return}if(action==='clear-rsvp'){preview.rsvp=null;rsvp='';render();return showRsvp()}}
function syncComposerIfOpen(){if($('#sheet-title').textContent==='Post to the family'){syncComposer();syncPostExtras()}}
function savePreviewForm(id){if(id==='composer-form')return publishPreviewPost();if(id==='comment-form'){if(!addComment(activePost,$('#comment-text').value,replyParent)){$('#comment-error').textContent='Enter a comment of 1–1,500 characters.';return}render();return showComments(activePost)}if(id==='profile-form'){const name=$('#profile-name').value.trim(),bio=$('#profile-bio').value.trim(),lines=$('#profile-socials').value.split('\n').map(s=>s.trim()).filter(Boolean),urls=lines.map(safeUrl);if(!name||name.length>60||bio.length>400||lines.length>4||urls.some(u=>!u)){$('#profile-error').textContent='Add a name (up to 60 characters), a short bio (400 max), and up to 4 valid http(s) links.';return}preview.profile={name,bio,socials:urls};close();go('you');return toast('Profile saved for this session.')}if(id==='details-form'){const date=$('#reunion-date').value,location=$('#reunion-location').value.trim(),schedule=$('#reunion-schedule').value.trim();if((date&&!/^\d{4}-\d{2}-\d{2}$/.test(date))||location.length>160||schedule.length>2000){$('#details-error').textContent='Check the date and field length limits.';return}preview.details={date,location,schedule};close();reunionTab='details';go('reunion');return toast('Reunion details saved in preview.')}if(id==='contact-form'){preview.contact={name:$('#contact-name').value.slice(0,60),email:$('#contact-email').value.slice(0,160),phone:$('#contact-phone').value.slice(0,40),optIn:$('#contact-optin').checked===true};close();return toast('Private contact preview saved for this session.')}if(id==='rsvp-form'){preview.rsvp={count:$('#rsvp-count').value,status:$('#rsvp-status').value};return act('save-rsvp')}}
document.addEventListener('submit',e=>{if(['composer-form','comment-form','reply-form','profile-form','details-form','contact-form','rsvp-form'].includes(e.target.id)){e.preventDefault();savePreviewForm(e.target.id)}});
document.addEventListener('input',e=>{if(e.target.id==='emoji-search'){emojiQuery=e.target.value.trim().toLowerCase();emojiPage=0;renderEmojiResults()}if(e.target.id==='post-text'){composer.text=e.target.value;if(e.inputType==='insertFromPaste'&&convertComposerLink(composer))updateComposerAttachment()}});
document.addEventListener('paste',e=>{if(e.target.id==='post-text')setTimeout(()=>{if($('#sheet-title').textContent==='Post to the family'){syncComposer();if(convertComposerLink(composer))updateComposerAttachment()}},0)});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){if(e.target.id==='post-text'){e.preventDefault();publishPreviewPost()}if(e.target.id==='comment-text'){e.preventDefault();savePreviewForm('comment-form')}}if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){const isReunion=e.target.dataset.reunionTab,isFamily=e.target.dataset.familyTab;if(isReunion||isFamily){e.preventDefault();const ids=isReunion?['details','plans','weekend']:['people','memories','tree'],current=isReunion||isFamily,index=e.key==='Home'?0:e.key==='End'?ids.length-1:(ids.indexOf(current)+(e.key==='ArrowRight'?1:-1)+ids.length)%ids.length;if(isReunion)reunionTab=ids[index];else familyTab=ids[index];render();$('#'+(isReunion?'reunion-':'tab-')+ids[index])?.focus?.()}}});
document.addEventListener('click',e=>{const poll=e.target.closest('[data-local-poll]');if(poll){const p=preview.posts.find(p=>p.id===poll.dataset.localPoll),n=Number(poll.dataset.option);if(p?.poll&&Number.isInteger(n)&&n>=0&&n<p.poll.options.length){p.poll.vote=n;render()}return}const photo=e.target.closest('[data-remove-photo]');if(photo){composer.photos?.splice(Number(photo.dataset.removePhoto),1);$('#post-photo-previews').innerHTML=photoDraftHtml();return}const custom=e.target.closest('[data-preview-action]');if(custom){doPreviewAction(custom.dataset.previewAction);return}const reaction=e.target.closest('[data-reaction-post]');if(reaction){if(toggleReaction(reaction.dataset.reactionPost,reaction.dataset.emoji)){render();if($('#sheet').open&&$('#sheet-title').textContent==='A little reaction')renderEmojiResults();toast('Reaction updated in preview.')}return}const picker=e.target.closest('[data-react-post]');if(picker)return showReactions(picker.dataset.reactPost);const comments=e.target.closest('[data-comment-post]');if(comments)return showComments(comments.dataset.commentPost);const reply=e.target.closest('[data-reply-id]');if(reply)return showComments(activePost,reply.dataset.replyId);const shirt=e.target.closest('[data-save-shirt]');if(shirt){preview.shirt={design:shirt.dataset.saveShirt,size:$('#shirt-size').value,quantity:Number($('#shirt-quantity').value)};preview.orderReviewed=false}});
document.addEventListener('change',e=>{if(e.target.id==='post-photos')loadPreviewPhotos(e.target.files);if(e.target.id==='serif-picker')chooseSerif(e.target.value);if(e.target.dataset.selectedPerson){selectedPeople=e.target.checked?[e.target.dataset.selectedPerson]:[]}});document.addEventListener('click',e=>{const rt=e.target.closest('[data-reunion-tab]');if(rt){reunionTab=rt.dataset.reunionTab;render();$('#reunion-'+reunionTab)?.focus?.();return}const ft=e.target.closest('[data-family-tab]');if(ft){familyTab=ft.dataset.familyTab;render();$('#tab-'+familyTab)?.focus?.();return}const ns=e.target.closest('[data-notification-scope]');if(ns){notificationScope=ns.dataset.notificationScope;remember('gw-notifications',notificationScope);notificationSettings();return}const theme=e.target.closest('[data-theme-choice]');if(theme){setTheme(theme.dataset.themeChoice);return}const font=e.target.closest('[data-font-choice]');if(font){setFont(font.dataset.fontChoice);return}const v=e.target.closest('[data-view]');if(v){hideProfile();close();go(v.dataset.view);return}const b=e.target.closest('[data-action]');if(b){hideProfile();if($('#sheet').open&&!['payment-unset'].includes(b.dataset.action))close();act(b.dataset.action);return}const p=e.target.closest('[data-vote]');if(p){vote=p.dataset.vote;render();return}const s=e.target.closest('[data-save-shirt]');if(s){shirtChoice=s.dataset.saveShirt+' · '+$('#shirt-size').value+' × '+$('#shirt-quantity').value;close();render();modal('Shirt choice saved',`<div class="step-nav"><span>1. RSVP</span><span class="current">2. Shirts ✓</span><span>3. Contribution</span></div><p class="muted">${escapeHtml(shirtChoice)}</p><p class="small muted" style="margin-top:10px">Preview only. No purchase was made.</p>${button('Next: contribution','contribute')}<div>${button('Back: RSVP','rsvp',true)}</div><div style="margin-top:10px">${button('Back to Home','home',true)}</div>`)}});$('#notifications').onclick=notifications;$('#post-fab').onclick=()=>act('compose');$('#sheet').addEventListener?.('cancel',syncComposerIfOpen);$('#close').onclick=close;$('#close').innerHTML=icon('close');$('.brand').onclick=e=>{e.preventDefault();go('home')};render();refreshWordmark();if(window.addEventListener)window.addEventListener('resize',fitWordmark);
